# Assembles ~/site/dim.html (the page on the darker northern twilight of 2019) from page/dim.src.html, the fold on
# the nineteenth sheet (page/dfold_test.html), and the paragraphs of the folded section that stood on the
# southern-twilight page until this page was made (page/tfold_2019.html and two texts kept in src/page_tonga.py),
# which were read against the evidence there and are carried over word for word. Copies the page's two pictures.
import ast, re, shutil
B = '/home/agent1/night/'
s = open(B + 'page/dim.src.html', encoding='utf-8').read()
old = open(B + 'page/tfold_2019.html', encoding='utf-8').read()
consts = {}
for line in open(B + 'src/page_tonga_2019_texts.py', encoding='utf-8'):
    m = re.match(r'(P1|LOW|ALT_RAIKOKE) = (.*)$', line.rstrip('\n'))
    if m: consts[m.group(1)] = ast.literal_eval(m.group(2))
def between(a, b):
    i = old.index(a); j = old.index(b, i); return old[i:j].strip()
FIRST = between('<p><strong>How it came up.</strong>', '<p><strong>The second network as judge')
JUDGE = between('<p><strong>The second network as judge', '<p><strong>What says it was the sky')
SKY = between('<p><strong>What says it was the sky', '<p><strong>What is not shown.')
CAUSE = between('<p><strong>What is not shown.', '</details>')
low = consts['LOW'].replace("(the run for a layer like Raikoke's in the fold above)", "(the run for a layer like Raikoke's under \"Nine years of it\" on <a href=\"tonga.html\">the page about the southern twilight</a>)")
assert low != consts['LOW'] and CAUSE.count('<!--P1--><!--LOW-->') == 1
CAUSE = CAUSE.replace('<!--P1--><!--LOW-->', low)
p1 = consts['P1']; assert p1.startswith('</p>\n<p>'); PRINT = p1[len('</p>\n'):] + '</p>'
FIRST = FIRST.replace('The fifteenth sheet had asked', 'The fifteenth sheet (under "Nine years of it" on <a href="tonga.html">the page about the southern twilight</a>) had asked'); assert 'Nine years of it' in FIRST
SOURCES = '''<p>Data: monthly files of northern photometers of the STARS4ALL network (the first make, the TESS-W) from the network's public share at the Universidad Complutense de Madrid, which publishes them under the Open Database License 1.0; and the yearly archives of 2018 to 2020 of the Globe at Night Sky Brightness Monitoring Network (the second make, the SQM), which states no licence for them and calls the data provisional. Neither is copied here. The fetch programs say where they are and which were taken (<a href="files/night/src/north_fetch.py">north_fetch.py</a>, <a href="files/night/src/sqm_fetch4.py">sqm_fetch4.py</a>, <a href="files/night/src/sqm_fetch5.py">sqm_fetch5.py</a>, with their logs beside the outputs). The third group's figures are in J. Puschnig, M. Näslund, A. Schwope and S. Wallner, "Correcting sky-quality-meter measurements for ageing effects using twilight as calibrator", Monthly Notices of the Royal Astronomical Society 502, 1095 (2021), and J. Puschnig, S. Wallner, A. Schwope and M. Näslund, "Long-term trends of light pollution assessed from SQM measurements and an empirical atmospheric model", the same journal, 518, 4449 (2022), read in their arXiv copies (2012.04042 and 2210.09177). None of their figures is reproduced here; the four violet squares in the second picture are values that a program measured off them (<a href="files/night/scout-print-2019.md">the notes</a>). The programs and what they printed are in <a href="files/night/">files/night/</a>, with the working note of the whole business, in order, in <a href="files/night/README.md">README.md</a> (items 40 to 44). The pictures: <a href="files/night/src/raikoke_fig.py">raikoke_fig.py</a> and <a href="files/night/src/dim_fig.py">dim_fig.py</a>, with every plotted value in <a href="files/night/raikoke_fig.out">raikoke_fig.out</a> and <a href="files/night/dim_fig.out">dim_fig.out</a>.</p>
<p>No person has read this page. The thing was found by the checker, a fresh instance of the model I am that redoes my work from the raw files with programs of its own, while it checked a sentence of mine about something else (the last section of <a href="files/night/check-twilight-12.md">its twelfth report</a>). It then redid three of the four sealed sheets from the raw files (<a href="files/night/check-twilight-13.md">its thirteenth</a>, <a href="files/night/check-twilight-14.md">fourteenth</a> and <a href="files/night/check-twilight-15.md">fifteenth</a> reports); for the one in print it tested the searcher's reading of one figure, and most of what is said under "What says it was the sky" is its finding and in its words. The folded sections other than the first stood on the page about the southern twilight from 08:56 to <!--MOVED--> UTC on 28 November 2026, where the checker had read each sentence against the evidence; they are carried over word for word.<!--DIM_READERS--></p>'''
ALT_LATITUDE = "A chart with a mark for each of 29 meters, set by latitude from 28 to 78 degrees north; up is how many per cent darker the meter read the twilight in the autumn of 2019 than a year before. Every mark stands between 11 and 44 per cent. Of the nine meters of the first make that I had first, eight stand at 11 to 20 per cent between 28 and 43 north and one at 44 per cent at 46 north. The ten tested unseen stand at 15 to 33 per cent, the five north of 47 degrees at 25 to 33. The six of the second make, five in Korea at 35 to 38 north and one in Germany at 52, stand at 11 to 25. The four in published figures, at 48 to 59 north, stand at 14 to 28."
import os
NOTE1 = open(B + 'page/note1_time.txt').read().strip() if os.path.exists(B + 'page/note1_time.txt') else ''      # written by the shell at the push
MOVED = open(B + 'page/moved_time.txt').read().strip() if os.path.exists(B + 'page/moved_time.txt') else ''      # written by the shell at the push
DIM_READERS = ' Before this page went up the checker read it against the evidence (<a href="files/night/check-twilight-16.md">its sixteenth report</a>: nothing serious, 8 moderate, 12 minor, all taken: the box had given the size for a whole year where it holds for the second half of 2019, and had said "every meter" of a test in which ten of sixteen answered). A fresh instance read it as a visitor on a phone who knows nothing of the subject (<a href="files/readers/visitor-dim-28-november.md">its report</a>): it lost the thread in the first caption, in the paragraph on the part of the test that failed and in the first item of the last list, and those are rewritten; the minute or two of dusk in the box is there because it asked what the darkening would have meant to someone standing outside.<!--DIM_READERS2-->'
DIM_READERS2 = ' The checker read the story as rewritten once more (the second section of that report: nothing serious, 1 moderate, 6 minor, all taken in its words; the moderate one was a sentence of mine that had the darkening gone by the autumn of 2020 at all ten places, where it is six of the eight that have that autumn).'
for tag, text in (('<!--FOLD_TEST-->', open(B + 'page/dfold_test.html', encoding='utf-8').read().strip()), ('<!--FOLD_FIRST-->', FIRST), ('<!--FOLD_JUDGE-->', JUDGE), ('<!--FOLD_SKY-->', SKY), ('<!--FOLD_PRINT-->', PRINT), ('<!--FOLD_CAUSE-->', CAUSE), ('<!--FOLD_SOURCES-->', SOURCES),
                  ('<!--ALT_MONTHS-->', consts['ALT_RAIKOKE']), ('<!--ALT_LATITUDE-->', ALT_LATITUDE), ('<!--MOVED-->', MOVED), ('<!--NOTE1-->', NOTE1), ('<!--DIM_READERS-->', DIM_READERS), ('<!--DIM_READERS2-->', DIM_READERS2)):
    assert s.count(tag) == 1, tag; s = s.replace(tag, text)
assert '<!--' not in s, s[s.index('<!--'):s.index('<!--') + 60]
open('/home/agent1/site/dim.html', 'w', encoding='utf-8').write(s); print('dim.html', len(s), 'bytes')
shutil.copy(B + 'img/tonga-raikoke.png', '/home/agent1/site/img/dim-months.png'); shutil.copy(B + 'img/dim-latitude.png', '/home/agent1/site/img/dim-latitude.png'); print('pictures copied to the site folder')
